from pathlib import Path
p=Path('/mnt/data/v56_work/app/web/index.html')
s=p.read_text(encoding='utf-8')
css=r'''<style id="v56-ultra-interactive-css">
.v56-overlay{position:fixed;inset:0;background:rgba(3,10,18,.78);backdrop-filter:blur(8px);z-index:9999;display:flex;align-items:stretch;justify-content:center;padding:18px;animation:v56fade .22s ease}
.v56-workspace{background:#f7f9fc;color:#142033;width:min(1500px,100%);height:100%;border-radius:20px;overflow:auto;box-shadow:0 25px 80px rgba(0,0,0,.35);animation:v56up .28s ease}
.v56-top{position:sticky;top:0;z-index:2;background:rgba(247,249,252,.96);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid #dfe5ed}.v56-top h2{margin:0;font-size:20px}.v56-close{border:0;background:#e9eef5;border-radius:10px;padding:9px 13px;font-size:18px;cursor:pointer}.v56-body{padding:20px}.v56-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.v56-grid2{display:grid;grid-template-columns:1.5fr 1fr;gap:16px;margin-top:16px}.v56-card{background:white;border:1px solid #e0e6ef;border-radius:15px;padding:16px;box-shadow:0 4px 14px rgba(20,32,51,.05)}.v56-kpi b{display:block;font-size:27px;margin-top:7px}.v56-muted{color:#68778c;font-size:13px}.v56-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.v56-btn{border:1px solid #cbd5e1;background:white;border-radius:9px;padding:9px 12px;cursor:pointer;font-weight:600}.v56-btn.primary{background:#163a63;color:#fff;border-color:#163a63}.v56-btn:hover{transform:translateY(-1px);box-shadow:0 5px 12px rgba(0,0,0,.08)}.v56-progress{height:8px;background:#e6ebf2;border-radius:99px;overflow:hidden}.v56-progress i{display:block;height:100%;width:0;background:linear-gradient(90deg,#2f6fed,#20a36a);transition:width .7s ease}.v56-chart{height:220px;display:flex;align-items:end;gap:9px;padding:15px 5px 5px;border-bottom:1px solid #dbe2ea}.v56-chart i{flex:1;min-width:10px;background:linear-gradient(to top,#315f96,#68a0dc);border-radius:6px 6px 0 0;animation:v56bar .7s ease both}.v56-line{height:210px;position:relative;background:repeating-linear-gradient(to bottom,transparent 0,transparent 41px,#e7ebf1 42px);border-left:1px solid #dbe2ea;border-bottom:1px solid #dbe2ea}.v56-line svg{width:100%;height:100%}.v56-table{width:100%;border-collapse:collapse;font-size:13px}.v56-table th,.v56-table td{padding:10px;border-bottom:1px solid #edf0f4;text-align:left}.v56-status{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #edf0f4}.v56-pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#e9f2ff;font-size:11px;font-weight:700}.v56-step{display:flex;gap:10px;align-items:flex-start;padding:10px 0}.v56-dot{width:24px;height:24px;border-radius:50%;background:#dfe8f4;display:grid;place-items:center;font-size:11px;font-weight:700}.v56-dot.on{background:#2f6fed;color:white}.v56-form{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.v56-form label{font-size:13px;font-weight:700}.v56-form input,.v56-form select,.v56-form textarea{width:100%;box-sizing:border-box;margin-top:6px;border:1px solid #cfd8e4;border-radius:9px;padding:10px;background:white}.v56-form textarea{min-height:80px}.v56-full{grid-column:1/-1}.v56-survey-shell{max-width:1100px;margin:auto}.v56-question{border:1px solid #dce4ed;background:white;border-radius:13px;padding:16px;margin:12px 0}.v56-option{display:block;padding:9px;border:1px solid #e2e7ee;border-radius:8px;margin:7px 0;cursor:pointer}.v56-toast{position:fixed;right:25px;bottom:25px;z-index:10001;background:#13253b;color:#fff;padding:12px 16px;border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,.25);animation:v56fade .2s ease}.v56-live{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:800;color:#16734d}.v56-live:before{content:'';width:7px;height:7px;border-radius:50%;background:#1fb56e;animation:v56pulse 1.2s infinite}
@keyframes v56fade{from{opacity:0}to{opacity:1}}@keyframes v56up{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}@keyframes v56bar{from{height:0}}@keyframes v56pulse{50%{opacity:.3;transform:scale(.7)}}
@media(max-width:900px){.v56-grid{grid-template-columns:repeat(2,1fr)}.v56-grid2,.v56-form{grid-template-columns:1fr}}@media(max-width:560px){.v56-grid{grid-template-columns:1fr}.v56-overlay{padding:0}.v56-workspace{border-radius:0}}
</style>'''
js=r'''<script id="v56-ultra-interactive-js">
(function(){
const inst=['fao','wfp','unicef','who','health','agriculture','monitoring'];
const labels={fao:'FAO Food Systems Intelligence',wfp:'WFP Food Security Intelligence',unicef:'UNICEF Child Nutrition Intelligence',who:'WHO Nutrition & NCD Intelligence',health:'Ministry of Health Command Center',agriculture:'Ministry of Agriculture Intelligence',monitoring:'Projects, Surveys & Nutrition Surveillance'};
const data={fao:{k:['Production forecast','Post-harvest loss','Price pressure','Food availability'],v:['82%','14.8%','67/100','76/100']},wfp:{k:['Food security','Diet affordability','Price pressure','Early warning'],v:['71/100','63/100','68/100','High']},unicef:{k:['Stunting','Wasting','Anaemia','EBF'],v:['24.1%','5.8%','41%','43%']},who:{k:['Diabetes','Hypertension','Obesity','CVD risk'],v:['7.4%','28.6%','11.8%','34/100']},health:{k:['NCD risk','Screening','Follow-up','Alerts'],v:['61/100','74%','68%','12']},agriculture:{k:['Forecast confidence','Losses','Market pressure','Climate risk'],v:['84%','15.2%','66/100','Moderate']},monitoring:{k:['Active projects','Survey rounds','Indicators','Quality'],v:['24','18','286','92%']}};
function esc(x){return String(x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function close(){document.getElementById('v56overlay')?.remove();}
window.v56Close=close;
function open(title,body){close();const o=document.createElement('div');o.id='v56overlay';o.className='v56-overlay';o.innerHTML=`<div class="v56-workspace"><div class="v56-top"><div><span class="v56-live">LIVE FRONT-END SIMULATION</span><h2>${esc(title)}</h2></div><button class="v56-close" onclick="v56Close()">✕</button></div>${body}</div>`;document.body.appendChild(o);o.addEventListener('click',e=>{if(e.target===o)close()});}
function toast2(t){const x=document.createElement('div');x.className='v56-toast';x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),2200)}
function bars(vals){return `<div class="v56-chart">${vals.map((v,i)=>`<i style="height:${Math.max(10,Math.min(96,v))}%;animation-delay:${i*70}ms"></i>`).join('')}</div>`}
function line(vals){const pts=vals.map((v,i)=>`${(i/(vals.length-1))*100},${100-v}`).join(' ');return `<div class="v56-line"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="#2f6fed" stroke-width="2.2" vector-effect="non-scaling-stroke"/><circle cx="${(vals.length-1)/(vals.length-1)*100}" cy="${100-vals.at(-1)}" r="2.5" fill="#163a63"/></svg></div>`}
function moduleWorkspace(id,feature){const d=data[id]||data.monitoring;const title=(labels[id]||'NUTRI.N°1 Intelligence')+' — '+feature;const vals=[52,61,58,67,63,72,76];return `<div class="v56-body"><div class="v56-grid">${d.k.map((k,i)=>`<div class="v56-card v56-kpi"><span class="v56-muted">${esc(k)}</span><b>${esc(d.v[i])}</b><span class="v56-live">Updated now</span></div>`).join('')}</div><div class="v56-actions"><button class="v56-btn primary" onclick="v56Recalc('${id}')">↻ Recalculate</button><button class="v56-btn" onclick="v56Drill('${id}','${esc(feature)}')">🔎 Drill down</button><button class="v56-btn" onclick="v56Scenario('${id}')">⚡ Run scenario</button><button class="v56-btn" onclick="v56Export('${esc(feature)}')">⇩ Export evidence</button></div><div class="v56-grid2"><div class="v56-card"><h3>📈 ${esc(feature)} trend</h3>${line(vals)}<p class="v56-muted">Interactive illustrative trend. Selecting a point opens its contextual record.</p><div class="v56-actions">${vals.map((v,i)=>`<button class="v56-btn" onclick="v56Point('${id}',${i},${v})">Period ${i+1}</button>`).join('')}</div></div><div class="v56-card"><h3>📊 Signal profile</h3>${bars([44,62,58,81,69,52])}<div class="v56-status"><span>Data quality</span><b>92%</b></div><div class="v56-status"><span>Provenance</span><b>Verified</b></div><div class="v56-status"><span>AI confidence</span><b>87%</b></div><div class="v56-status"><span>Decision state</span><b>Actionable</b></div></div></div><div class="v56-grid2"><div class="v56-card"><h3>🗺️ Geographic drill-down</h3><table class="v56-table"><tr><th>Area</th><th>Signal</th><th>Risk</th><th>Action</th></tr>${['National','Region A','District B','District C'].map((x,i)=>`<tr><td>${x}</td><td>${58+i*6}/100</td><td>${i===2?'High':i===1?'Watch':'Moderate'}</td><td><button class="v56-btn" onclick="v56Geo('${esc(x)}')">Open</button></td></tr>`).join('')}</table></div><div class="v56-card"><h3>🧠 Decision engine</h3><div class="v56-step"><span class="v56-dot on">1</span><div><b>Signal detected</b><br><span class="v56-muted">Multi-source indicator change identified.</span></div></div><div class="v56-step"><span class="v56-dot on">2</span><div><b>AI fusion</b><br><span class="v56-muted">Context, geography and trend combined.</span></div></div><div class="v56-step"><span class="v56-dot on">3</span><div><b>Recommendation</b><br><span class="v56-muted">Priority action generated for review.</span></div></div><button class="v56-btn primary" onclick="v56Decision('${esc(feature)}')">Open decision</button></div></div></div>`}
window.v56Recalc=function(id){toast2('Recalculating '+(labels[id]||'intelligence')+'…');setTimeout(()=>toast2('Indicators synchronized • AI confidence 89%'),900)};
window.v56Drill=function(id,f){open((labels[id]||'Intelligence')+' — Drill-down',moduleWorkspace(id,f+' — detailed analysis'))};
window.v56Scenario=function(id){open((labels[id]||'Intelligence')+' — Scenario Lab',`<div class="v56-body"><div class="v56-card"><h3>⚡ Interactive scenario</h3><p class="v56-muted">Adjust a shock and observe how dependent indicators respond.</p><div class="v56-form"><label>Shock intensity<input id="v56shock" type="range" min="0" max="100" value="35" oninput="v56ScenarioCalc()"></label><label>Duration<select id="v56duration" onchange="v56ScenarioCalc()"><option>1 month</option><option>3 months</option><option>6 months</option><option>12 months</option></select></label></div><div id="v56scenarioOut" style="margin-top:16px"></div></div></div>`);v56ScenarioCalc()};
window.v56ScenarioCalc=function(){const s=+document.getElementById('v56shock').value;document.getElementById('v56scenarioOut').innerHTML=`${bars([80-s*.3,70-s*.45,60-s*.55,52+s*.25,48+s*.4])}<div class="v56-grid">${[['Food access',Math.max(15,82-s*.5)],['Nutrition risk',Math.min(95,35+s*.55)],['Price pressure',Math.min(98,42+s*.48)],['Response priority',Math.min(100,28+s*.65)]].map(x=>`<div class="v56-card v56-kpi"><span>${x[0]}</span><b>${Math.round(x[1])}/100</b></div>`).join('')}</div>`};
window.v56Export=function(f){toast2('Evidence package generated: '+f+' • PDF/CSV/JSON ready')};window.v56Point=function(id,i,v){open('Contextual record',`<div class="v56-body"><div class="v56-card"><h3>Period ${i+1} intelligence record</h3><div class="v56-grid"><div class="v56-card v56-kpi"><span>Indicator value</span><b>${v}/100</b></div><div class="v56-card v56-kpi"><span>Quality</span><b>94%</b></div><div class="v56-card v56-kpi"><span>AI confidence</span><b>88%</b></div><div class="v56-card v56-kpi"><span>Status</span><b>Reviewed</b></div></div><div class="v56-actions"><button class="v56-btn primary" onclick="v56Decision('Period ${i+1}')">Open decision</button><button class="v56-btn" onclick="v56Close()">Back</button></div></div></div>`) };window.v56Geo=function(x){toast2('Opening GIS record for '+x+'…');setTimeout(()=>open('GIS — '+x, moduleWorkspace('monitoring','Geographic intelligence — '+x)),600)};window.v56Decision=function(f){open('Decision Center — '+f,`<div class="v56-body"><div class="v56-card"><span class="v56-pill">RECOMMENDATION READY</span><h2>Priority intervention package</h2><p>Signal combination indicates a decision-worthy change. Review the recommended intervention, target geography, owner and expected outcome before committing.</p><div class="v56-form"><label>Priority<select><option>High</option><option>Medium</option><option>Watch</option></select></label><label>Owner<select><option>Programme team</option><option>District team</option><option>Policy unit</option></select></label><label class="v56-full">Action<textarea>Deploy targeted response and activate follow-up monitoring.</textarea></label></div><div class="v56-actions"><button class="v56-btn primary" onclick="toast2('Intervention drafted and added to M&E queue')">Create intervention</button><button class="v56-btn" onclick="toast2('Decision brief generated')">Generate brief</button></div></div></div>`) };
function survey(){open('Survey Builder — New Survey',`<div class="v56-body v56-survey-shell"><div class="v56-card"><div class="v56-grid"><div><span class="v56-muted">Step 1</span><b> Design</b></div><div><span class="v56-muted">Step 2</span><b> Questionnaire</b></div><div><span class="v56-muted">Step 3</span><b> Sampling</b></div><div><span class="v56-muted">Step 4</span><b> Publish</b></div></div></div><div class="v56-card" style="margin-top:14px"><h3>📝 Survey definition</h3><div class="v56-form"><label>Survey name<input id="svName" value="National Nutrition & Food Security Survey 2026"></label><label>Country<select><option>Togo</option><option>Ghana</option><option>Senegal</option><option>Nigeria</option></select></label><label>Survey type<select><option>Nutrition & Anthropometry</option><option>Dietary Diversity</option><option>Food Security</option><option>Maternal & Child Nutrition</option><option>NCD Risk Factors</option></select></label><label>Population<select><option>Households</option><option>Children 0–59 months</option><option>Women 15–49</option><option>Adults 18+</option></select></label><label class="v56-full">Objective<textarea>Estimate nutrition, dietary and food-security indicators and identify priority geographies.</textarea></label></div><div class="v56-actions"><button class="v56-btn primary" onclick="v56SurveyNext()">Continue to questionnaire →</button><button class="v56-btn" onclick="v56Close()">Cancel</button></div></div></div>`)}
window.v56SurveyNext=function(){const n=document.getElementById('svName')?.value||'New Survey';open('Survey Builder — Questionnaire',`<div class="v56-body v56-survey-shell"><div class="v56-card"><span class="v56-pill">DRAFT • ${esc(n)}</span><h3>Questionnaire designer</h3><div class="v56-actions"><button class="v56-btn" onclick="v56AddQ()">＋ Add question</button><button class="v56-btn" onclick="toast2('Question bank opened')">Question bank</button><button class="v56-btn primary" onclick="v56Sampling()">Sampling →</button></div><div id="v56questions"><div class="v56-question"><b>Q1. What is the age of the child?</b><p class="v56-muted">Numeric • required • validation: 0–59 months</p></div><div class="v56-question"><b>Q2. What foods were consumed yesterday?</b><p class="v56-muted">Multiple selection • dietary diversity module</p></div><div class="v56-question"><b>Q3. Household food access status</b><p class="v56-muted">Validated food-security response module</p></div></div></div></div>`)};
window.v56AddQ=function(){const q=document.createElement('div');q.className='v56-question';q.innerHTML='<b>New question</b><input placeholder="Enter question text" style="width:100%;margin-top:8px;padding:9px;border:1px solid #ccd5e1;border-radius:8px"><select style="width:100%;margin-top:8px;padding:9px;border:1px solid #ccd5e1;border-radius:8px"><option>Single choice</option><option>Multiple choice</option><option>Numeric</option><option>Text</option><option>Date</option></select>';document.getElementById('v56questions').appendChild(q)};
window.v56Sampling=function(){open('Survey Builder — Sampling & Publish',`<div class="v56-body v56-survey-shell"><div class="v56-grid"><div class="v56-card v56-kpi"><span>Target sample</span><b>2,400</b></div><div class="v56-card v56-kpi"><span>Clusters</span><b>120</b></div><div class="v56-card v56-kpi"><span>Estimated duration</span><b>21 days</b></div><div class="v56-card v56-kpi"><span>Readiness</span><b>86%</b></div></div><div class="v56-card" style="margin-top:14px"><h3>📍 Sampling frame</h3><table class="v56-table"><tr><th>Stratum</th><th>Clusters</th><th>Households</th><th>Status</th></tr><tr><td>Urban</td><td>60</td><td>1,200</td><td>Ready</td></tr><tr><td>Rural</td><td>60</td><td>1,200</td><td>Ready</td></tr></table><div class="v56-actions"><button class="v56-btn primary" onclick="v56PublishSurvey()">✓ Validate & publish</button><button class="v56-btn" onclick="v56Close()">Save draft</button></div></div></div>`)};
window.v56PublishSurvey=function(){toast2('Survey published • mobile collection workspace initialized');setTimeout(()=>open('Survey published — Collection Control Room',`<div class="v56-body"><div class="v56-grid">${[['Enumerators','48'],['Devices online','45/48'],['Forms today','126'],['Quality pass','97%']].map(x=>`<div class="v56-card v56-kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div>${bars([20,35,48,58,72,86])}<div class="v56-actions"><button class="v56-btn primary" onclick="toast2('Live collection map opened')">🗺 Open field map</button><button class="v56-btn" onclick="toast2('Data quality rules running')">✓ Run quality checks</button></div></div>`),700)};
function me(){open('Project M&E Workspace',`<div class="v56-body"><div class="v56-grid">${data.monitoring.k.map((k,i)=>`<div class="v56-card v56-kpi"><span>${k}</span><b>${data.monitoring.v[i]}</b></div>`).join('')}</div><div class="v56-actions"><button class="v56-btn primary" onclick="v56ME('logframe')">📐 Logical framework</button><button class="v56-btn" onclick="v56ME('indicators')">📊 Indicator registry</button><button class="v56-btn" onclick="v56ME('results')">🎯 Results dashboard</button><button class="v56-btn" onclick="v56ME('evaluation')">🧪 Evaluation</button></div><div class="v56-grid2"><div class="v56-card"><h3>Outcome performance</h3>${line([48,51,55,57,63,68,76])}</div><div class="v56-card"><h3>Target achievement</h3>${bars([62,71,58,83,76])}</div></div></div>`)}
window.v56ME=function(mode){const titles={logframe:'Logical Framework Designer',indicators:'Indicator Registry',results:'Results Dashboard',evaluation:'Evaluation Workspace'};open(titles[mode],moduleWorkspace('monitoring',titles[mode]))};
function surveillance(){open('Routine Nutrition Surveillance Control Room',`<div class="v56-body"><div class="v56-grid">${[['Feeds active','18'],['Indicators streaming','286'],['Records today','12,840'],['Alerts','7']].map(x=>`<div class="v56-card v56-kpi"><span>${x[0]}</span><b>${x[1]}</b><span class="v56-live">Streaming</span></div>`).join('')}</div><div class="v56-actions"><button class="v56-btn primary" onclick="v56Surv('dashboard')">📊 Surveillance dashboard</button><button class="v56-btn" onclick="v56Surv('alerts')">🚨 Alert queue</button><button class="v56-btn" onclick="v56Surv('feeds')">📡 Data feeds</button><button class="v56-btn" onclick="v56Surv('bulletin')">📑 Generate bulletin</button></div><div class="v56-grid2"><div class="v56-card"><h3>Live indicator trend</h3>${line([38,42,45,43,51,59,64])}</div><div class="v56-card"><h3>Signal composition</h3>${bars([74,52,66,44,81,58])}</div></div></div>`)}
window.v56Surv=function(mode){const t={dashboard:'Surveillance Dashboard',alerts:'Early Warning Alert Queue',feeds:'Data Feed Monitor',bulletin:'Nutrition Surveillance Bulletin'};open(t[mode],moduleWorkspace('monitoring',t[mode]))};
function generic(id,feature){open((labels[id]||id)+' — '+feature,moduleWorkspace(id,feature))}
function intercept(e){const b=e.target.closest('button');if(!b)return;const view=b.closest('.view');if(!view||!inst.includes(view.id))return;const txt=(b.innerText||b.textContent||'').trim().toLowerCase();if(view.id==='monitoring'){if(txt.includes('create survey')){e.preventDefault();e.stopImmediatePropagation();survey();return}if(txt.includes('open m&e')){e.preventDefault();e.stopImmediatePropagation();me();return}if(txt.includes('open surveillance')){e.preventDefault();e.stopImmediatePropagation();surveillance();return}}
const specific=[['explore gis','GIS Intelligence'],['recalculate','Live Recalculation'],['drill down','Analytical Drill-down'],['run scenario','Scenario Lab'],['export evidence','Evidence Export'],['open decision','Decision Center']];for(const [needle,feat] of specific){if(txt.includes(needle)){e.preventDefault();e.stopImmediatePropagation();generic(view.id,feat);return}}
if(b.classList.contains('btn')&&txt&&!['open citizen dashboard'].some(x=>txt.includes(x))){e.preventDefault();e.stopImmediatePropagation();generic(view.id,b.innerText.trim());return}}
document.addEventListener('click',intercept,true);
window.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
})();
</script>'''
# insert before body close
s=s.replace('</body></html>',css+js+'</body></html>')
# update version markers/readme-like title in html
s=s.replace('V55','V56',1)
p.write_text(s,encoding='utf-8')
